   '[{"raw": "1 a 1⁄2 krajec chlieb celozrnný (75 g)", "name": "chlieb celozrnný", "grams": 75.0}, {"raw": "130 g kuracie prsia bez kostí", "name": "kuracie prsia bez kostí", "grams": 130.0}, {"raw": "3 ks rajčiny (225 g)", "name": "rajčiny", "grams": 225.0}, {"raw": "6 ks mandle (6 g)", "name": "mandle", "grams": 6.0}, {"raw": "3 x miska rukola (51 g)", "name": "rukola", "grams": 51.0}]'::jsonb,
