   '[{"raw": "indiánska ryža (70 g)", "name": "indiánska ryža", "grams": 70}, {"raw": "tvrdý syr 20 % (80 g)", "name": "tvrdý syr 20 %", "grams": 80}, {"raw": "olivový olej (7 g)", "name": "olivový olej", "grams": 7}, {"raw": "hrášok (60 g)", "name": "hrášok", "grams": 60}, {"raw": "pečiarka poľná/šampiňóny (100 g)", "name": "pečiarka poľná/šampiňóny", "grams": 100}, {"raw": "pór (70 g)", "name": "pór", "grams": 70}, {"raw": "mrkva (40 g)", "name": "mrkva", "grams": 40}]'::jsonb,
