   '[{"raw": "1 x stredne veľká cibuľa (75 g)", "name": "cibuľa", "grams": 75.0}, {"raw": "2 x polovica ks tekvica Hokkaido (800 g)", "name": "tekvica Hokkaido", "grams": 800.0}, {"raw": "6 PL olivový olej (72 g)", "name": "olivový olej", "grams": 72.0}, {"raw": "4 ks rajčiny (300 g)", "name": "rajčiny", "grams": 300.0}, {"raw": "2 ks mrkva (170 g)", "name": "mrkva", "grams": 170.0}, {"raw": "8 g kurkuma", "name": "kurkuma", "grams": 8.0}, {"raw": "2 ČL ľanové semená (6 g)", "name": "ľanové semená", "grams": 6.0}, {"raw": "2 ČL sezamové semená (6 g)", "name": "sezamové semená", "grams": 6.0}, {"raw": "1⁄2 PL olej tekvicový (6 g)", "name": "olej tekvicový", "grams": 6.0}, {"raw": "1500 ml voda (1500 g)", "name": "voda", "grams": 1500.0}]'::jsonb,
