   '[{"raw": "fazuľa biela (50 g)", "name": "fazuľa biela", "grams": 50}, {"raw": "slepačie vajce (80 g)", "name": "slepačie vajce", "grams": 80}, {"raw": "špaldová celozrnná hrubá múka (30 g)", "name": "špaldová celozrnná hrubá múka", "grams": 30}, {"raw": "jogurt biely (150 g)", "name": "jogurt biely", "grams": 150}, {"raw": "olivový olej (5 g)", "name": "olivový olej", "grams": 5}, {"raw": "kukurica z konzervy (15 g)", "name": "kukurica z konzervy", "grams": 15}, {"raw": "paprika červená (30 g)", "name": "paprika červená", "grams": 30}, {"raw": "šalát hlávkový (15 g)", "name": "šalát hlávkový", "grams": 15}, {"raw": "špenát (8 g)", "name": "špenát", "grams": 8}]'::jsonb,
