   '[{"raw": "chlieb rascový (70 g)", "name": "chlieb rascový", "grams": 70}, {"raw": "olivový olej (15 g)", "name": "olivový olej", "grams": 15}, {"raw": "kuracie prsia bez kostí (110 g)", "name": "kuracie prsia bez kostí", "grams": 110}, {"raw": "jogurt biely (100 g)", "name": "jogurt biely", "grams": 100}, {"raw": "ľadový šalát (40 g)", "name": "ľadový šalát", "grams": 40}, {"raw": "sójová omáčka (5 g)", "name": "sójová omáčka", "grams": 5}, {"raw": "cesnak (1 g)", "name": "cesnak", "grams": 1}, {"raw": "šťava citrónová (6 g / 6 ml)", "name": "šťava citrónová", "grams": 6}]'::jsonb,
