   '[{"raw": "8 x ČL parmezán (40 g)", "name": "parmezán", "grams": 40.0}, {"raw": "8 PL jogurt bielkovinový napr. Skyr Pilos (160 g)", "name": "jogurt bielkovinový", "grams": 160.0}, {"raw": "2 ks mrkva (170 g)", "name": "mrkva", "grams": 170.0}, {"raw": "290 g cuketa (cukina)", "name": "cuketa", "grams": 290.0}, {"raw": "1 ČL olivový olej (5 g)", "name": "olivový olej", "grams": 5.0}, {"raw": "2 x priemerný kus zeler buľvový (100 g)", "name": "zeler buľvový", "grams": 100.0}, {"raw": "2 a 1⁄2 x PL sójová omáčka (27.5 g)", "name": "sójová omáčka", "grams": 27.5}, {"raw": "1⁄2 PL balsamico kalamata napr. (Papadimitriou) (5 g)", "name": "balsamico kalamata", "grams": 5.0}]'::jsonb,
   479, 40.7, 44.3, 17.2, 9.7, 100, 1, true),
  ('Losos so šampiňónovou omáčkou (so sójovou smotanou)', 'hlavne', 25, 'Lososa umyte, osušte, osoľte. Opečte na oleji z oboch strán asi 5 minút a dajte na tanier. Poduste nadrobno nakrájanú cibuľu a na plátky nakrájané očistené, umyté šampiňóny. Pokvapkajte citrónovou šťavou. Potom zalejte smotanou a krátko povarte. Omáčkou polejte lososa. Konzumujte s prílohou.

