   '[{"raw": "tvrdý syr 20 % (100 g)", "name": "tvrdý syr 20 %", "grams": 100}, {"raw": "strúhanka (30 g)", "name": "strúhanka", "grams": 30}, {"raw": "zemiaky neskoré (50 g)", "name": "zemiaky neskoré", "grams": 50}, {"raw": "olivový olej (4 g)", "name": "olivový olej", "grams": 4}, {"raw": "brokolica (80 g)", "name": "brokolica", "grams": 80}, {"raw": "jogurt biely (70 g)", "name": "jogurt biely", "grams": 70}, {"raw": "zeler buľvový (20 g)", "name": "zeler buľvový", "grams": 20}, {"raw": "uhorky (25 g)", "name": "uhorky", "grams": 25}]'::jsonb,
